const fs=require('node:fs'),vm=require('node:vm'),path=require('node:path');
const W=__dirname,R=path.join(W,'si-batch-improvements');
const html=fs.readFileSync(path.join(R,'auctions.html'),'utf8');
const code=html.slice(html.indexOf('  async function load() {'),html.indexOf('  document.addEventListener("DOMContentLoaded", load);'));
function harness(fetch){
 const calls=[],elements=new Map(),get=id=>{if(!elements.has(id))elements.set(id,{textContent:'',innerHTML:''});return elements.get(id);};
 const scope={fetch:(...args)=>(calls.push(args[0]),fetch(...args)),FEED:'/data/auction-desk.json',FEED_S3:'synthetic-secondary',window:{},$:get,
 renderBanner:()=>{},renderReactions:()=>{},renderOps:()=>{},renderBuybacks:()=>{},renderCalendar:()=>{},renderDays:()=>{},renderTape:()=>{},renderTenors:()=>{},wireExplainer:()=>{}};
 vm.createContext(scope);vm.runInContext(code,scope);return {scope,calls};
}
(async()=>{
 const hung=harness(async()=>({ok:true,json:()=>new Promise(()=>{})}));let completed=false;hung.scope.load().then(()=>completed=true);
 await new Promise(r=>setTimeout(r,30));
 const error=harness(async()=>({ok:true,json:async()=>({error:'Synthetic gateway error'})}));await error.scope.load();
 const partial=harness(async()=>({ok:true,json:async()=>({engine:'justhodl-auction-desk',buybacks:{operations:{}}})}));
 const render=[];partial.scope.renderBanner=()=>render.push('banner painted');partial.scope.renderBuybacks=()=>{throw new TypeError('synthetic invalid operations shape');};
 let failure;try{await partial.scope.load();}catch(e){failure=e.message;}
 const report={scope:'Reviewed current load function only, isolated synthetic transports/render spies; no network or archived-code execution',
  hung_body:{completed_after_known_never_settling_body:completed,requested_routes:hung.calls},
  error_shaped_success:{requested_routes:error.calls,accepted_packet:error.scope.window.__AUCTION_DESK},
  rendering_failure:{steps:render,uncaught:failure,requested_routes:partial.calls},
  diagnosis:'No transport/body deadline; any truthy successful JSON prevents fallback; rendering exceptions escape after earlier sections repaint'};
 fs.writeFileSync(path.join(W,'stage416-loader-reproduced.json'),JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify(report));
})();
